from pathlib import Path
P=Path(r'E:\CodexOutputs\ChemFlowAI\frontend\src')
(P/'main.tsx').write_text(r'''import React,{useCallback,useEffect,useState} from 'react';import {createRoot} from 'react-dom/client';import {BrowserRouter,Routes,Route,Link,useNavigate,useParams} from 'react-router-dom';import {FlaskConical,Layers3,Workflow,Database,ShieldCheck,ChevronLeft,ChevronRight,Check,Lock,Save,Plus,ArrowRight,LoaderCircle,Download,House,FolderOpen,Info} from 'lucide-react';import {api,fmt} from './api';import {Badge,Panel,Q,Notice,Modal,Empty} from './components/ui';import {Steps} from './pages/Steps';import type {Project,ProjectSpec} from './types';import './styles/theme.css';
const names=['需求与设计基准','物性与数据校核','模型选择与验证','路线与分离筛选','流程搭建与收敛','能量与设备分析','参数与方案优化','经济与环境评价','复核与成果交付'];
const subtitles=['将已知进料、产品目标与工程边界转为唯一设计基准。','检查数据完整性、单位、适用范围与物性缺口。','候选模型由工程规则推荐，经人工批准后进入路线决策。','从结构、控制、公用工程与技术风险做出路线选择。','现有动态流程资产与 SimulationIR、结果和审查状态绑定。','检查设备负荷、外部质量衡算和可用能量数据。','定义变量、边界和目标；无优化器时仅保存问题与参考比较。','缺失输入保持未计算，所有可支持指标使用确定性公式。','复核完整工程链条，区分工作流完成与独立数值验证。'];
function TopBar({p,step}:{p?:Project;step?:number}){return <header className="topbar"><Link to="/" className="brand"><span className="brand-mark"><FlaskConical size={23}/></span><div><strong>ChemFlow AI｜智模拟·绿化工</strong><small>{p?'VALIDATION TASK / '+p.name:'ENGINEERING ORCHESTRATION WORKBENCH'}</small></div></Link><div className="status-row">{step&&<Badge tone="cyan">STEP {String(step).padStart(2,'0')} / 09</Badge>}<Badge tone={p?.mode==='blind'?'amber':'cyan'}>{p?.backend==='dwsim'?'DWSIM · NOT CONNECTED':p?.backend==='aspen_mcp'?'ASPEN MCP · NOT CONNECTED':'REFERENCE REPLAY'}</Badge><span className="optional"><Badge tone={p?.status==='COMPLETE'?'green':'amber'}>{p?.status||'OFFLINE FIRST'}</Badge></span><span className="optional"><Badge tone="green">TRACEABILITY ON</Badge></span></div></header>}
function Landing(){return <><TopBar/><main className="landing"><span className="eyebrow">AI辅助化工流程设计与多目标优化</span><h1>从工程需求到可追溯的设计交付</h1><p className="intro">AI 组织与解释，专业模拟器负责计算，工程师确认关键决策。通过九步连续工作流，完成从设计基准到模拟诊断、方案评价和成果复核。</p><div className="flex-row"><Link to="/workspace/new"><button className="primary"><Plus size={16}/>新建工程验证任务</button></Link><Link to="/workspace"><button><FolderOpen size={16}/>打开工作区</button></Link><Badge tone="cyan">LOCAL · OFFLINE</Badge></div><div className="landing-grid"><div className="landing-card"><Workflow/><h2>连续工程闭环</h2><p>真实步骤门槛、人工确认、历史查看和上游修改后的计算失效。</p></div><div className="landing-card"><Database/><h2>来源与结果分离</h2><p>设计输入、参考回放和最终标准答案分层存储，结果附带来源与单位。</p></div><div className="landing-card"><ShieldCheck/><h2>验证而不冒充求解</h2><p>Demo 使用 Reference Replay；盲验证等待真实 DWSIM 或 Aspen MCP 连接。</p></div></div><div className="boundary"><Notice tone="cyan">当前 AI Inspector 由可审计工程规则和六个封装 Skills 驱动；未连接在线大模型。Reference Replay 不代表新一轮独立 ChemFlow 模拟。</Notice></div><Panel title="九步工程规程" kicker="WORKFLOW" className="report"><div className="form-grid">{names.map((n,i)=><div key={n} className="field-block"><small className="eyebrow">STEP {String(i+1).padStart(2,'0')}</small><h3>{n}</h3></div>)}</div></Panel></main></>}
function Dashboard(){const [projects,setProjects]=useState<Project[]>([]);const [error,setError]=useState('');useEffect(()=>{api('/projects').then(setProjects).catch(e=>setError(e.message))},[]);return <><TopBar/><main className="dashboard"><div className="dashboard-header"><div><span className="eyebrow">VALIDATION TASKS</span><h1>工程工作区</h1><p>保存的任务、审核与计算状态会在刷新后恢复。</p></div><Link to="/workspace/new"><button className="primary"><Plus size={16}/>新建任务</button></Link></div>{error&&<Notice tone="red">{error}</Notice>}{!projects.length&&!error?<Empty title="开始第一个工程验证任务" text="选择设计输入体系，确认工作模式，再沿九步工作流推进。"/>:<div className="project-grid">{projects.map(p=><article key={p.id} className="project-card"><Badge tone={p.status==='COMPLETE'?'green':'cyan'}>{p.status}</Badge><h2>{p.name}</h2><p>{p.dataset==='pdh'?'丙烷脱氢':'四氢糠醇制吡啶'} · {p.mode==='demo'?'Workflow Demo':'Blind Validation'}</p><div className="progress"><i style={{width:p.completed.length/9*100+'%'}}/></div><div className="feed-title"><small>{p.completed.length} / 9 已确认</small><Badge>{p.backend}</Badge></div><Link to={'/workspace/'+p.id+'/step/'+p.max_step}><button className="full-width">继续工程任务 <ArrowRight size={15}/></button></Link></article>)}</div>}</main></>}
function NewTask(){const nav=useNavigate();const [dataset,setDataset]=useState<'pdh'|'pyridine'>('pdh');const [name,setName]=useState('丙烷脱氢 · 工程验证');const [mode,setMode]=useState('demo');const [backend,setBackend]=useState('reference_replay');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const create=async()=>{setBusy(true);setError('');try{const p=await api('/projects','POST',{name,dataset,mode,backend});nav('/workspace/'+p.id+'/step/1')}catch(e:any){setError(e.message)}finally{setBusy(false)}};return <><TopBar/><main className="new-task"><Link to="/workspace">← 返回工作区</Link><span className="eyebrow" style={{marginTop:24}}>CREATE VALIDATION TASK</span><h1>建立工程设计基准</h1><Panel title="验证输入体系"><div className="task-options">{[['pdh','丙烷脱氢','C₃H₈ → C₃H₆ + H₂'],['pyridine','四氢糠醇制吡啶','THFA + NH₃ · 多级分离']].map(([id,title,sub])=><button key={id} className={'task-option '+(dataset===id?'active':'')} onClick={()=>{setDataset(id as any);setName(title+' · 工程验证')}}><FlaskConical size={22}/><strong>{title}</strong><span>{sub}</span><small>加载已知输入，不预先加载 Aspen 下游答案</small></button>)}</div><label>任务名称<input value={name} onChange={e=>setName(e.target.value)} maxLength={100}/></label><div className="form-grid two" style={{marginTop:18}}><label>运行模式<select value={mode} onChange={e=>{setMode(e.target.value);setBackend(e.target.value==='demo'?'reference_replay':'dwsim')}}><option value="demo">Workflow Demo · 参考回放</option><option value="blind">Blind Validation · 独立验证</option></select></label><label>模拟器后端<select value={backend} onChange={e=>setBackend(e.target.value)}>{mode==='demo'&&<option value="reference_replay">ReferenceReplayAdapter</option>}<option value="dwsim">DWSIM · 未连接</option><option value="aspen_mcp">Aspen MCP · 未连接</option></select></label></div><div style={{marginTop:20}}><Notice>{mode==='demo'?'回放只验证工作流集成，不是独立数值验证。':'尚未配置独立求解器。可完成上游工程决策，到 Step 05 将阻止伪造结果。'}</Notice></div>{error&&<Notice tone="red">{error}</Notice>}<div className="button-row"><button className="primary" onClick={create} disabled={!name.trim()||busy}>{busy?<LoaderCircle size={15} className="spinner"/>:<ArrowRight size={15}/>}创建并进入 Step 01</button></div></Panel></main></>}
function Inspector({p,selection,onSource}:{p:Project;selection:any;onSource:(s:any)=>void}){const s=selection?.kind==='stream'?p.result?.streams[selection.id]:null;const u=selection?.kind==='equipment'?p.ir?.units.find((x:any)=>x.id===selection.id):null;return <aside className="inspector">{selection&&<Panel title={selection.id} kicker={selection.kind==='stream'?'STREAM INSPECTOR':'EQUIPMENT INSPECTOR'}>{s?<><Badge tone={s.temperature.status==='ANOMALY'?'amber':'cyan'}>{s.temperature.status==='ANOMALY'?'SOURCE ANOMALY':'ASPEN REFERENCE'}</Badge>{[['temperature','温度'],['pressure','压力'],['mass_flow','质量流量'],['phase','相态']].map(([k,l])=><div className="keyvalue" key={k}><span>{l}</span><Q q={s[k]} onSource={onSource}/></div>)}<div className="inspector-label">COMPOSITION</div>{Object.keys(s.composition).length?Object.entries(s.composition).map(([k,v]:any)=><div className="keyvalue" key={k}><span>{k}</span><Q q={v} onSource={onSource}/></div>):<p>组分结果未提供，不推断。</p>}<button className="source-button" onClick={()=>onSource(s)}>完整来源与验证状态 ⓘ</button></>:u?<><div className="keyvalue"><span>类型</span><b>{u.type}</b></div><div className="keyvalue"><span>已审候选模型</span><b>{p.model}</b></div><div className="keyvalue"><span>求解状态</span><Badge tone="amber">{p.result?'REPLAY_NOT_SOLVED':'PENDING'}</Badge></div><div className="keyvalue"><span>独立收敛</span><span>NOT ASSESSED</span></div><p style={{marginTop:12}}>未提供独立设备操作参数。入口、出口条件可点击相邻流股查看；候选模型不改变存档结果。</p></>:<p>结果尚未加载。设备与流股已连接到 IR，温度、压力和流量暂不显示。</p>}</Panel>}<Panel title="Engineering Copilot" kicker="AI INSPECTOR · RULE ENGINE" action={<Layers3 size={17} className="cyan"/>}><Badge tone="amber">HUMAN REVIEW</Badge><div className="inspector-label">OBSERVATION</div><p className="highlight">{p.inspector.observation}</p><div className="inspector-label">EVIDENCE</div><ul>{p.inspector.evidence.map((s:string)=><li key={s}>{s}</li>)}</ul><div className="inspector-label">RISK</div><p>{p.inspector.risk}</p><div className="inspector-label">RECOMMENDATION</div><p>{p.inspector.recommendation}</p><div className="inspector-label">ACTION REQUIRED</div><p>{p.inspector.action_required}</p><div className="inspector-label">ACTIVE SKILL</div><p className="mono">{p.inspector.skill}</p></Panel><Panel title="工程事件记录" kicker="TRACEABILITY"><div className="events">{[...p.events].reverse().map((e:any,i)=><div key={i}><small>{new Date(e.time).toLocaleTimeString()}</small><br/>{e.message}</div>)}</div></Panel></aside>}
function Workspace(){const {projectId,step:stepParam}=useParams();const step=Number(stepParam||9);const nav=useNavigate();const [p,setP]=useState<Project|null>(null);const [draft,setDraft]=useState<ProjectSpec|null>(null);const [model,setModel]=useState('');const [route,setRoute]=useState('');const [source,setSource]=useState<any>(null);const [selection,setSelection]=useState<any>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [toast,setToast]=useState('');const [ack,setAck]=useState(false);const [note,setNote]=useState('');const [confirmModal,setConfirmModal]=useState<null|(()=>Promise<void>)>(null);
 const reload=useCallback(async()=>{const x=await api('/projects/'+projectId+'/steps/'+step);setP(x);setDraft(structuredClone(x.spec));setModel(x.model||'');setRoute(x.route||'');return x},[projectId,step]);
 useEffect(()=>{setP(null);setError('');setAck(false);setNote('');setSelection(null);reload().catch(e=>setError(e.message))},[reload]);
 const run=async(fn:()=>Promise<any>)=>{setBusy(true);setError('');try{return await fn()}catch(e:any){setError(e.message);return null}finally{setBusy(false)}};
 const select=useCallback((s:any)=>setSelection(s),[]);
 const saveDraft=async()=>{if(!p||!draft)return;if(JSON.stringify(draft)===JSON.stringify(p.spec)){setToast('当前数据已保存。');return}const commit=async()=>{await run(async()=>{await api('/projects/'+projectId+'/spec','PUT',{spec:draft,invalidate:true});setToast('设计基准已保存；后续计算与审核已失效。');await reload();nav('/workspace/'+projectId+'/step/1')})};if(p.completed.length)setConfirmModal(()=>commit);else await commit()};
 const next=()=>run(async()=>{if(!p||!draft)return;if(step<p.max_step||p.completed.includes(step)){nav('/workspace/'+projectId+'/step/'+Math.min(step+1,9));return}if(step===1&&JSON.stringify(draft)!==JSON.stringify(p.spec))await api('/projects/'+projectId+'/spec','PUT',{spec:draft,invalidate:false});const r=await api('/projects/'+projectId+'/steps/'+step+'/confirm','POST',{review_ack:ack,note,model,route});setAck(false);setToast('阶段已确认并保存。');if(step===9)await reload();else nav('/workspace/'+projectId+'/step/'+r.max_step)});
 const reopen=()=>setConfirmModal(()=>async()=>{await run(async()=>{await api('/projects/'+projectId+'/reopen/'+step,'POST',{invalidate:true});await reload();setToast('当前步骤已重新打开，下游结果已失效。')})});
 if(!p||!draft)return <><TopBar/><main className="dashboard">{error?<><Notice tone="red">{error}</Notice><Link to="/workspace"><button>返回工作区</button></Link></>:<Empty title="恢复工程状态" text="正在读取本地保存的设计基准与审核记录…"/>}</main></>;
 const canEdit=step===p.max_step&&!p.completed.includes(step);const past=!canEdit;const reportPage=!stepParam;return <><TopBar p={p} step={step}/><aside className="sidebar"><span className="eyebrow" style={{padding:'0 10px'}}>ENGINEERING NAVIGATION</span><Link to="/"><House size={16}/>首页</Link><Link to="/workspace"><FolderOpen size={16}/>任务工作区</Link><div className="nav-section">WORKFLOW / 九步工程闭环</div>{names.map((n,i)=><button data-testid={'nav-step-'+(i+1)} className={'nav-step '+(step===i+1?'active ':'')+(p.completed.includes(i+1)?'done':'')} disabled={i+1>p.max_step} key={n} onClick={()=>nav('/workspace/'+p.id+'/step/'+(i+1))}><span className="num">{p.completed.includes(i+1)?<Check size={13}/>:String(i+1).padStart(2,'0')}</span>{n}{i+1>p.max_step&&<Lock size={11}/>}</button>)}<div className="sidebar-footer"><Badge tone="cyan">RULE ENGINE · OFFLINE</Badge><p style={{marginTop:10,fontSize:10}}>Canonical ProjectSpec<br/>Revision {p.revision} · 本机持久化</p></div></aside><main className="work"><nav className="stepper" aria-label="九步进度">{names.map((n,i)=><button key={n} title={n} className={step===i+1?'current':p.completed.includes(i+1)?'complete':''} disabled={i+1>p.max_step} onClick={()=>nav('/workspace/'+p.id+'/step/'+(i+1))}>{p.completed.includes(i+1)?'✓ ':''}{String(i+1).padStart(2,'0')}</button>)}</nav><div className="step-heading"><div><span className="eyebrow">STAGE EXECUTION / {p.dataset.toUpperCase()} · S{String(step).padStart(2,'0')}</span><h1>{reportPage?'工程验证报告':`Step ${String(step).padStart(2,'0')} · ${names[step-1]}`}</h1><p>{subtitles[step-1]}</p></div><Badge tone={p.completed.includes(step)?'green':'amber'}>{p.completed.includes(step)?'REVIEWED':'HUMAN REVIEW'}</Badge></div>{error&&<div style={{marginBottom:14}}><Notice tone="red">{error}</Notice></div>}<div className="workspace-grid"><div className="main-stack">{reportPage&&p.status!=='COMPLETE'?<Empty title="报告尚未完成" text="完成 Step 09 人工复核后可导出。"/>:<Steps p={p} step={step} draft={draft} setDraft={setDraft} model={model} setModel={setModel} route={route} setRoute={setRoute} onSource={setSource} onSelect={select} run={run} reload={reload} busy={busy} canEdit={canEdit}/>}<Panel title="本阶段人工复核" kicker="ENGINEER APPROVAL"><label className="review-check"><input type="checkbox" aria-label="人工复核确认" checked={ack} disabled={!canEdit} onChange={e=>setAck(e.target.checked)}/>我已检查本阶段依据，接受明确标注的缺失项与演示限制</label><label className="review-note">审核备注{step===5&&p.review?.issues.length?'（存在异常时必填）':'（可选）'}<input aria-label="审核备注" value={note} disabled={!canEdit} onChange={e=>setNote(e.target.value)} placeholder="记录判断依据、未解决风险及后续行动"/></label>{past&&<div className="button-row"><Badge tone="green">已记录人工确认</Badge>{step<=8&&<button onClick={reopen}>重新打开本阶段</button>}</div>}</Panel></div><Inspector p={p} selection={selection} onSource={setSource}/></div></main><footer className="bottom-bar"><div className="left"><button onClick={()=>nav(step>1?'/workspace/'+p.id+'/step/'+(step-1):'/workspace')}><ChevronLeft size={15}/>返回上一步</button>{step===1&&<button onClick={saveDraft} disabled={busy}><Save size={15}/>保存设计基准</button>}</div><div className="right"><small className="muted">{busy?'执行工程操作…':p.completed.length+' / 9 已确认 · 本地保存'}</small><button className="primary" data-testid="confirm-next" onClick={next} disabled={busy||(canEdit&&!ack)||(step===9&&p.status==='COMPLETE')}>{busy?<LoaderCircle size={16} className="spinner"/>:null}{step===9?(p.status==='COMPLETE'?'工作流已完成':'完成复核与交付'):past?'查看下一步':'确认并进入下一阶段'}<ChevronRight size={16}/></button></div></footer>{source!==null&&<Modal title="数据来源与追溯" onClose={()=>setSource(null)}><pre>{JSON.stringify(source,null,2)}</pre></Modal>}{confirmModal&&<Modal title="下游计算失效确认" onClose={()=>setConfirmModal(null)}><Notice>该修改会导致后续计算结果失效，是否重新计算？既有模拟结果、优化、评价和审核记录会从对应步骤起清除。</Notice><div className="button-row"><button onClick={()=>setConfirmModal(null)}>取消修改</button><button className="primary" onClick={async()=>{const fn=confirmModal;setConfirmModal(null);await fn()}}>确认修改并使下游失效</button></div></Modal>}{toast&&<div className="toast"><button onClick={()=>setToast('')}>×</button>{toast}</div>}</>}
function App(){return <BrowserRouter><Routes><Route path="/" element={<Landing/>}/><Route path="/workspace" element={<Dashboard/>}/><Route path="/workspace/new" element={<NewTask/>}/><Route path="/workspace/:projectId/step/:step" element={<Workspace/>}/><Route path="/workspace/:projectId/report" element={<Workspace/>}/><Route path="*" element={<><TopBar/><main className="dashboard"><Empty title="页面不存在" text="请从工作区继续已有任务。"/><Link to="/workspace">返回工作区</Link></main></>}/></Routes></BrowserRouter>}
createRoot(document.getElementById('root')!).render(<App/>);
''',encoding='utf-8')
print('App Shell, router, task dashboard, intake and report entry created.')
